const MongoTransform = require('../../../../../src/Adapters/Storage/Mongo/MongoTransform');
const Parse = require('parse/node').Parse;

const { transformConstraint } = MongoTransform;
const INVALID_JSON = Parse.Error.INVALID_JSON;
const COMMAND_UNAVAILABLE = Parse.Error.COMMAND_UNAVAILABLE;

function expectParseError(fn, code, message) {
  let thrown;
  try {
    fn();
  } catch (error) {
    thrown = error;
  }
  expect(thrown).toBeInstanceOf(Parse.Error);
  expect(thrown.code).toBe(code);
  expect(thrown.message).toBe(message);
}

describe('transformConstraint', () => {
  describe('general contract', () => {
    it('returns the CannotTransform sentinel for non-object constraints', () => {
      const sentinel = transformConstraint(null, null, 'field');
      expect(typeof sentinel).toBe('function');

      for (const constraint of [undefined, 'a string', 42, false, true]) {
        expect(transformConstraint(constraint, null, 'field')).toBe(sentinel);
      }
    });

    it('returns the same CannotTransform sentinel for an object that is not a constraint', () => {
      const sentinel = transformConstraint(null, null, 'field');
      expect(transformConstraint({ plain: 'value' }, null, 'field')).toBe(sentinel);
    });

    it('returns an empty object for an empty constraint object', () => {
      expect(transformConstraint({}, null, 'field')).toStrictEqual({});
    });

    it('throws for an unknown operator beginning with $', () => {
      expectParseError(
        () => transformConstraint({ $where: '1 === 1' }, null, 'field'),
        INVALID_JSON,
        'bad constraint: $where'
      );
    });
  });

  describe('comparison operators', () => {
    it.each(['$lt', '$lte', '$gt', '$gte', '$exists', '$ne', '$eq'])(
      'passes a primitive value through for %s',
      operator => {
        expect(transformConstraint({ [operator]: 7 }, null, 'score')).toStrictEqual({
          [operator]: 7,
        });
      }
    );

    it('transforms a pointer object into a className$objectId string at the top level', () => {
      const pointer = { __type: 'Pointer', className: '_User', objectId: 'abc123' };
      expect(transformConstraint({ $eq: pointer }, null, 'user')).toStrictEqual({
        $eq: '_User$abc123',
      });
    });

    it('prefixes a top-level string with the field target class for pointer fields', () => {
      const field = { type: 'Pointer', targetClass: '_User' };
      expect(transformConstraint({ $eq: 'abc123' }, field, 'user')).toStrictEqual({
        $eq: '_User$abc123',
      });
    });

    it('transforms a date JSON atom into a Date', () => {
      const date = { __type: 'Date', iso: '2021-02-03T04:05:06.789Z' };
      expect(transformConstraint({ $lt: date }, null, 'createdAt')).toStrictEqual({
        $lt: new Date('2021-02-03T04:05:06.789Z'),
      });
    });

    it('transforms a GeoPoint JSON atom into a [longitude, latitude] pair', () => {
      const point = { __type: 'GeoPoint', longitude: 11.5, latitude: -7.25 };
      expect(transformConstraint({ $eq: point }, null, 'location')).toStrictEqual({
        $eq: [11.5, -7.25],
      });
    });

    it('transforms a File JSON atom into its name', () => {
      const file = { __type: 'File', name: 'avatar.png' };
      expect(transformConstraint({ $eq: file }, null, 'photo')).toStrictEqual({
        $eq: 'avatar.png',
      });
    });

    it('throws when a top-level atom cannot be transformed', () => {
      expectParseError(
        () => transformConstraint({ $eq: { custom: 'value' } }, null, 'field'),
        INVALID_JSON,
        'bad atom: {"custom":"value"}'
      );
    });

    it('uses the interior atom transformer for nested query keys', () => {
      const pointer = { __type: 'Pointer', className: '_User', objectId: 'abc123' };
      expect(transformConstraint({ $eq: pointer }, null, 'nested.user')).toStrictEqual({
        $eq: pointer,
      });
      expect(transformConstraint({ $eq: { custom: 'value' } }, null, 'nested.field')).toStrictEqual({
        $eq: { custom: 'value' },
      });
    });

    it('does not add the target class prefix for nested pointer-field keys', () => {
      const field = { type: 'Pointer', targetClass: '_User' };
      expect(transformConstraint({ $eq: 'abc123' }, field, 'nested.user')).toStrictEqual({
        $eq: 'abc123',
      });
    });

    it('uses the interior atom transformer for Array fields', () => {
      const field = { type: 'Array' };
      const pointer = { __type: 'Pointer', className: '_User', objectId: 'abc123' };
      expect(transformConstraint({ $eq: pointer }, field, 'users')).toStrictEqual({
        $eq: pointer,
      });
    });

    it('turns a $regex wrapper into a RegExp for nested keys', () => {
      expect(
        transformConstraint({ $eq: { $regex: '^foo' } }, null, 'nested.name')
      ).toStrictEqual({ $eq: new RegExp('^foo') });
    });
  });

  describe('$relativeTime', () => {
    beforeEach(() => {
      jest.useFakeTimers();
      jest.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
    });

    afterEach(() => {
      jest.useRealTimers();
    });

    it.each(['$lt', '$lte'])('resolves a future relative time for %s', operator => {
      expect(
        transformConstraint(
          { [operator]: { $relativeTime: 'in 2 days' } },
          { type: 'Date' },
          'createdAt'
