  describe('$in and $nin', () => {
    it.each(['$in', '$nin'])('passes an array of primitives through for %s', operator => {
      expect(transformConstraint({ [operator]: [1, 2, 3] }, null, 'score')).toStrictEqual({
        [operator]: [1, 2, 3],
      });
    });

    it.each(['$in', '$nin'])('flattens one level of nested arrays for %s', operator => {
      expect(
        transformConstraint({ [operator]: [1, [2, 3], 4] }, null, 'score')
      ).toStrictEqual({ [operator]: [1, 2, 3, 4] });
