    it('transforms pointer atoms in $in with a top-level transformer', () => {
      const pointer = { __type: 'Pointer', className: '_User', objectId: 'abc123' };
      expect(transformConstraint({ $in: [pointer] }, null, 'user')).toStrictEqual({
        $in: ['_User$abc123'],
      });
    });

    it('uses the interior atom transformer in $in for Array fields', () => {
      const pointer = { __type: 'Pointer', className: '_User', objectId: 'abc123' };
      expect(
        transformConstraint({ $in: [pointer] }, { type: 'Array' }, 'users')
      ).toStrictEqual({ $in: [pointer] });
    });

    it('transforms date atoms in $nin', () => {
      const date = { __type: 'Date', iso: '2020-01-01T00:00:00.000Z' };
      expect(transformConstraint({ $nin: [date] }, null, 'createdAt')).toStrictEqual({
        $nin: [new Date('2020-01-01T00:00:00.000Z')],
      });
