      const pointer = { __type: 'Pointer', className: '_User', objectId: 'abc123' };
      expect(transformConstraint({ $all: [date, pointer] }, null, 'values')).toStrictEqual({
        $all: [new Date('2020-01-01T00:00:00.000Z'), pointer],
