      expect(transformConstraint({ $all: [first, second] }, null, 'name')).toStrictEqual({
        $all: [new RegExp('^\\Qfoo\\E'), new RegExp('^\\Qbar\\E')],
      });
    });

    it('rejects a mix of regex and non-regex values', () => {
