        'bad $text: $language, should be string'
      );
    });

    it('rejects a non-boolean $caseSensitive', () => {
      expectParseError(
        () =>
          transformConstraint(
            { $text: { $search: { $term: 'hello', $caseSensitive: 'yes' } } },
