'use strict';

const mongodb = require('mongodb');
const Parse = require('parse/node').Parse;

const {
  mongoObjectToParseObject,
} = require('../../../../../src/Adapters/Storage/Mongo/MongoTransform');
const loggerModule = require('../../../../../src/logger');

const schemaWith = (fields = {}) => ({ fields });

const originalLogger = loggerModule.getLogger();
let fakeLogger;

beforeEach(() => {
  fakeLogger = {
    warn: jest.fn(),
    info: jest.fn(),
    error: jest.fn(),
    debug: jest.fn(),
    log: jest.fn(),
  };
  loggerModule.setLogger(fakeLogger);
});

afterEach(() => {
  loggerModule.setLogger(originalLogger);
});

describe('mongoObjectToParseObject - atomic values', () => {
  const schema = schemaWith();

  it('returns a string unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', 'hello', schema)).toBe('hello');
  });

  it('returns a number unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', 42.5, schema)).toBe(42.5);
  });

  it('returns a boolean unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', false, schema)).toBe(false);
    expect(mongoObjectToParseObject('TestClass', true, schema)).toBe(true);
  });

  it('returns undefined unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', undefined, schema)).toBeUndefined();
  });

  it('throws for a symbol value', () => {
    expect(() => mongoObjectToParseObject('TestClass', Symbol('nope'), schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
  });

  it('throws for a function value', () => {
    expect(() => mongoObjectToParseObject('TestClass', () => {}, schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
  });

  it('throws for a bigint value as an unknown js type', () => {
    expect(() => mongoObjectToParseObject('TestClass', BigInt(10), schema)).toThrow(
      'unknown js type'
    );
  });
});

describe('mongoObjectToParseObject - null, arrays and bson scalars', () => {
  const schema = schemaWith();

  it('returns null for a null object', () => {
    expect(mongoObjectToParseObject('TestClass', null, schema)).toBeNull();
  });

  it('returns an empty array unchanged', () => {
    expect(mongoObjectToParseObject('TestClass', [], schema)).toEqual([]);
  });

  it('maps arrays element by element', () => {
    expect(mongoObjectToParseObject('TestClass', [1, 'two', true, null], schema)).toEqual([
      1,
      'two',
      true,
      null,
    ]);
  });

  it('does not apply key transformations to objects inside arrays', () => {
    const value = [{ _id: 'abc', someKey: 1 }];
    expect(mongoObjectToParseObject('TestClass', value, schema)).toEqual([
      { _id: 'abc', someKey: 1 },
    ]);
  });

  it('encodes dates inside arrays', () => {
    const date = new Date('2021-03-04T05:06:07.089Z');
    expect(mongoObjectToParseObject('TestClass', [date], schema)).toEqual([
      { __type: 'Date', iso: '2021-03-04T05:06:07.089Z' },
    ]);
  });

  it('converts mongodb Long values inside arrays to numbers', () => {
    expect(mongoObjectToParseObject('TestClass', [mongodb.Long.fromNumber(1234)], schema)).toEqual([
      1234,
    ]);
  });

  it('encodes a top level Date like Parse._encode', () => {
    const date = new Date('2020-01-02T03:04:05.678Z');
    const result = mongoObjectToParseObject('TestClass', date, schema);
    expect(result).toEqual({ __type: 'Date', iso: '2020-01-02T03:04:05.678Z' });
    expect(result).toEqual(Parse._encode(date));
  });

  it('converts a mongodb Long to a number', () => {
    expect(mongoObjectToParseObject('TestClass', mongodb.Long.fromNumber(77), schema)).toBe(77);
  });

  it('extracts the value of a mongodb Double', () => {
    expect(mongoObjectToParseObject('TestClass', new mongodb.Double(3.25), schema)).toBe(3.25);
  });

  it('converts a mongodb Binary to a Bytes object', () => {
    const binary = new mongodb.Binary(Buffer.from('hello'));
    expect(mongoObjectToParseObject('TestClass', binary, schema)).toEqual({
      __type: 'Bytes',
      base64: Buffer.from('hello').toString('base64'),
    });
  });
});

describe('mongoObjectToParseObject - reserved field name conversions', () => {
