      'Found an unexpected reserved key, dropping it.',
      'TestClass',
      '_unknownReserved'
    );
  });

  it('keeps the __type key', () => {
    expect(mongoObjectToParseObject('TestClass', { __type: 'Something' }, schema)).toEqual({
      __type: 'Something',
    });
  });

  it('recursively transforms nested objects for regular keys', () => {
    const result = mongoObjectToParseObject(
      'TestClass',
