    expect(result).toEqual({ avatar: { __type: 'File', name: 'profile.png' } });
  });

  it('leaves a File column value untouched when it is not a file database object', () => {
    const schema = schemaWith({ avatar: { type: 'File' } });
    const result = mongoObjectToParseObject('TestClass', { avatar: { name: 'x' } }, schema);
    expect(result).toEqual({ avatar: { name: 'x' } });
  });

  it('converts a GeoPoint column value', () => {
    const schema = schemaWith({ location: { type: 'GeoPoint' } });
    const result = mongoObjectToParseObject('TestClass', { location: [13.5, 52.25] }, schema);
    expect(result).toEqual({
      location: { __type: 'GeoPoint', latitude: 52.25, longitude: 13.5 },
    });
  });

  it('converts a Polygon column value', () => {
    const schema = schemaWith({ area: { type: 'Polygon' } });
    const polygon = {
      type: 'Polygon',
      coordinates: [
        [
          [13, 52],
          [14, 53],
          [15, 54],
          [13, 52],
        ],
      ],
    };
    const result = mongoObjectToParseObject('TestClass', { area: polygon }, schema);
    expect(result).toEqual({
      area: {
        __type: 'Polygon',
        coordinates: [
          [52, 13],
          [53, 14],
          [54, 15],
          [52, 13],
        ],
      },
    });
  });

  it('converts a Bytes column holding a mongodb Binary', () => {
    const schema = schemaWith({ data: { type: 'Bytes' } });
    const result = mongoObjectToParseObject(
      'TestClass',
      { data: new mongodb.Binary(Buffer.from('abc')) },
      schema
    );
    expect(result).toEqual({
      data: { __type: 'Bytes', base64: Buffer.from('abc').toString('base64') },
    });
  });

  it('converts a Bytes column holding a base64 string', () => {
    const schema = schemaWith({ data: { type: 'Bytes' } });
    const result = mongoObjectToParseObject('TestClass', { data: 'aGVsbG8=' }, schema);
    expect(result).toEqual({ data: { __type: 'Bytes', base64: 'aGVsbG8=' } });
