  it('does not convert a base64 looking string for a non-Bytes column', () => {
    const schema = schemaWith({ label: { type: 'String' } });
    const result = mongoObjectToParseObject('TestClass', { label: 'aGVsbG8=' }, schema);
    expect(result).toEqual({ label: 'aGVsbG8=' });
  });
});

describe('mongoObjectToParseObject - relation fields', () => {
