const INSTALLATION_ID = 'installation-1';

function createRequest({ body = {}, auth = { isMaster: false, installationId: INSTALLATION_ID }, providers = {} } = {}) {
  const authDataManager = {
    getValidatorForProvider: jest.fn(provider => providers[provider]),
  };
  const req = {
    body,
    auth,
    config: {
      auth: {},
      headers: { 'x-test-header': 'value' },
      ip: '127.0.0.1',
      loggerController: {},
      database: {},
      authDataManager,
