  };
  return req;
}

function createProviderAdapter({ challenge = jest.fn(), validator = jest.fn() } = {}) {
  return {
    validator,
    adapter: { challenge },
  };
}

async function getRejection(promise) {
  try {
    await promise;
  } catch (error) {
    return error;
  }
  throw new Error('Expected the promise to reject, but it resolved.');
}

function expectParseError(error, code, message) {
  expect(error).toBeInstanceOf(Parse.Error);
  expect(error.code).toBe(code);
  expect(error.message).toBe(message);
}

