          authenticationStep: 'challenge',
          provider: 'otp',
          user: 'authenticated-user',
        })
      );
    });

    it('stops executing challenges after the first failure', async () => {
      const firstChallenge = jest.fn().mockRejectedValue(new Error('first failed'));
      const secondChallenge = jest.fn().mockResolvedValue('should not run');
      const req = createRequest({
        body: {
          challengeData: {
            alpha: { value: 1 },
            zed: { value: 2 },
          },
        },
