  req.get = function (name) {
    const value = headers[String(name).toLowerCase()];
    return value === undefined ? undefined : value;
  };
  return req;
}

function createRes() {
  const res = {
    statusCode: undefined,
    body: undefined,
    ended: undefined,
  };
  res.status = jest.fn(function (code) {
    res.statusCode = code;
    return res;
  });
  res.json = jest.fn(function (body) {
    res.body = body;
    return res;
  });
  res.end = jest.fn(function (body) {
    res.ended = body;
    return res;
  });
  return res;
}

function setupGlobalMocks() {
  AppCache.get.mockReset();
  Config.get.mockReset();
  auth.Auth.mockClear();
}

function flushPendingTasks() {
  return new Promise(resolve => setImmediate(resolve));
}

async function runHeaders(req, res, next) {
  const result = await handleParseHeaders(req, res, next);
  // `handleRateLimit` is invoked without awaiting by the production code, so give
  // its pending microtasks a chance to complete before assertions.
  await flushPendingTasks();
  return result;
}

describe('handleParseHeaders', () => {
  let appConfig;
  let next;

  beforeEach(() => {
    setupGlobalMocks();
    appConfig = createConfig();
    AppCache.get.mockImplementation(id => (id === 'testAppId' ? appConfig : undefined));
    next = jest.fn();
  });

  describe('application id resolution and request info', () => {
    it('populates req.info, req.config and request metadata for a header-authenticated request', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-session-token': 'r:abc',
          'x-parse-installation-id': 'install-1',
          'x-parse-client-key': 'clientKeyValue',
          'x-parse-windows-key': 'dotNetKeyValue',
          'x-parse-rest-api-key': 'restKeyValue',
          'x-parse-javascript-key': 'jsKeyValue',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info).toEqual({
        appId: 'testAppId',
        sessionToken: 'r:abc',
        masterKey: undefined,
        maintenanceKey: undefined,
        installationId: 'install-1',
        clientKey: 'clientKeyValue',
        javascriptKey: 'jsKeyValue',
        dotNetKey: 'dotNetKeyValue',
        restAPIKey: 'restKeyValue',
        context: {},
        app: appConfig,
      });
      expect(req.config).toBe(appConfig);
      expect(req.config.headers).toBe(req.headers);
      expect(req.config.ip).toBe('127.0.0.1');
      // A session token is present, so authentication is resolved later by
      // handleParseSession and no Auth object is built here.
      expect(auth.Auth).not.toHaveBeenCalled();
      expect(next).toHaveBeenCalledTimes(1);
      expect(res.status).not.toHaveBeenCalled();
    });

    it('falls back to Config.get and loads keys when req.config is not set', async () => {
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      const res = createRes();
      Config.get.mockReturnValue(appConfig);

      await runHeaders(req, res, next);

      expect(Config.get).toHaveBeenCalledWith('testAppId', 'http://localhost:1337/parse');
      expect(appConfig.loadKeys).toHaveBeenCalledTimes(1);
      expect(req.config).toBe(appConfig);
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('returns 403 when no application id can be resolved', async () => {
      const req = createReq();
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.ended).toBe('{"error":"unauthorized"}');
      expect(next).not.toHaveBeenCalled();
      expect(req.info).toBeUndefined();
    });

    it('returns 403 when the header application id is not in the app cache', async () => {
      const req = createReq({ headers: { 'x-parse-application-id': 'unknownApp' } });
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.ended).toBe('{"error":"unauthorized"}');
      expect(next).not.toHaveBeenCalled();
    });

    it('returns 403 when the session token header is not a string', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-session-token': 12345,
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });
  });

  describe('cloud context header', () => {
    it('parses a valid JSON object context', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-cloud-context': '{"foo":"bar","nested":{"a":1}}',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.context).toEqual({ foo: 'bar', nested: { a: 1 } });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it.each([
      ['unparseable json', '{not-json'],
      ['an array', '[1,2,3]'],
      ['a primitive', '"a string"'],
      ['null', 'null'],
    ])('rejects %s as malformed context', async (_label, headerValue) => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-cloud-context': headerValue,
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(400);
      expect(res.json).toHaveBeenCalledWith({
        code: Parse.Error.INVALID_JSON,
        error: 'Invalid object for context.',
      });
      expect(next).not.toHaveBeenCalled();
    });
  });

  describe('http basic authentication', () => {
    it('takes the app id and javascript key from the Authorization header', async () => {
      const basicConfig = createConfig({ javascriptKey: 'js-from-basic' });
      AppCache.get.mockImplementation(id => {
        if (id === 'basicApp') {
          return basicConfig;
        }
        return undefined;
      });
      const encoded = Buffer.from('basicApp:javascript-key=js-from-basic').toString('base64');
      const req = createReq({ headers: { authorization: `Basic ${encoded}` } });
      req.config = basicConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.appId).toBe('basicApp');
      expect(req.info.javascriptKey).toBe('js-from-basic');
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('ignores basic auth credentials for unknown apps', async () => {
      const encoded = Buffer.from('unknownApp:masterKey').toString('base64');
      const req = createReq({ headers: { authorization: `Basic ${encoded}` } });
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it('authenticates as master via basic auth master key', async () => {
      const encoded = Buffer.from('testAppId:masterKey').toString('base64');
      const req = createReq({ headers: { authorization: `Basic ${encoded}` } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(auth.Auth).toHaveBeenCalledTimes(1);
      expect(auth.Auth.mock.calls[0][0]).toMatchObject({ isMaster: true });
      expect(next).toHaveBeenCalledTimes(1);
    });
  });

  describe('body based application id', () => {
    it('extracts all SDK body fields and strips them from the body', async () => {
      const req = createReq({
        body: {
          _ApplicationId: 'testAppId',
          _JavaScriptKey: 'jsKey',
          _ClientVersion: '1.2.3',
          _InstallationId: 'install-from-body',
          _SessionToken: 'r:body-session',
          _MasterKey: 'masterKey',
          _context: { from: 'body' },
          _ContentType: 'application/json',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.appId).toBe('testAppId');
      expect(req.info.javascriptKey).toBe('jsKey');
      expect(req.info.installationId).toBe('install-from-body');
      expect(req.info.sessionToken).toBe('r:body-session');
      expect(req.info.masterKey).toBe('masterKey');
      expect(req.info.context).toEqual({ from: 'body' });
      expect(req.headers['content-type']).toBe('application/json');
      expect(req.body).toEqual({});
      expect(auth.Auth.mock.calls[0][0]).toMatchObject({ isMaster: true });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('defaults the javascript key to an empty string when absent', async () => {
      const req = createReq({ body: { _ApplicationId: 'testAppId' } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.javascriptKey).toBe('');
      expect(req.info.context).toEqual({});
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('removes the Unity _noBody key before processing', async () => {
      const req = createReq({
        headers: { 'x-parse-application-id': 'testAppId' },
        body: { _noBody: true, other: 'value' },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.body).toEqual({ other: 'value' });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('removes _RevocableSession from body supplied requests', async () => {
      const req = createReq({
        body: { _ApplicationId: 'testAppId', _RevocableSession: true, key: 'value' },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.body).toEqual({ key: 'value' });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('returns 403 when the body application id is unknown', async () => {
      const req = createReq({ body: { _ApplicationId: 'unknownApp' } });
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it('returns 403 when the header master key does not match the app master key', async () => {
      const req = createReq({
        headers: { 'x-parse-master-key': 'a-different-master-key' },
        body: { _ApplicationId: 'testAppId' },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it.each([
      ['_InstallationId', { _InstallationId: 42 }],
      ['_SessionToken', { _SessionToken: { not: 'a string' } }],
      ['_MasterKey', { _MasterKey: 99 }],
      ['_ContentType', { _ContentType: ['application/json'] }],
    ])('returns 403 when body %s is not a string', async (_field, extra) => {
      const req = createReq({ body: Object.assign({ _ApplicationId: 'testAppId' }, extra) });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it('parses a JSON string body context', async () => {
      const req = createReq({
        body: { _ApplicationId: 'testAppId', _context: '{"a":1,"b":[2]}' },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.context).toEqual({ a: 1, b: [2] });
      expect(req.body._context).toBeUndefined();
      expect(next).toHaveBeenCalledTimes(1);
    });

    it.each([
      ['unparseable json', '{nope'],
      ['an array', '[1,2]'],
      ['a string', '"hello"'],
    ])('rejects a body context that is %s', async (_label, value) => {
      const req = createReq({
        body: { _ApplicationId: 'testAppId', _context: value },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(400);
      expect(res.json).toHaveBeenCalledWith({
        code: Parse.Error.INVALID_JSON,
        error: 'Invalid object for context.',
      });
      expect(next).not.toHaveBeenCalled();
    });

    it('treats a null body context as no context and removes the key', async () => {
      const req = createReq({
        body: { _ApplicationId: 'testAppId', _context: null },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.context).toEqual({});
      expect('_context' in req.body).toBe(false);
      expect(next).toHaveBeenCalledTimes(1);
    });
  });

  describe('file upload via JSON body', () => {
    it('parses a JSON buffer body and repopulates req.body from base64', async () => {
      const payload = {
        _ApplicationId: 'testAppId',
        fileData: '/tmp/some-file',
        base64: Buffer.from('hello file').toString('base64'),
      };
      const req = createReq({ body: Buffer.from(JSON.stringify(payload)) });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(Buffer.isBuffer(req.body)).toBe(true);
      expect(req.body.toString()).toBe('hello file');
      expect(req.fileData).toBe('/tmp/some-file');
      expect(req.info.appId).toBe('testAppId');
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('returns 403 when the buffer body is not valid JSON', async () => {
      const req = createReq({ body: Buffer.from('definitely not json') });
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it('returns 403 when the parsed file body has a non-string base64 value', async () => {
      const req = createReq({
        body: Buffer.from(JSON.stringify({ _ApplicationId: 'testAppId', base64: 1234 })),
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });
  });

  describe('key based authentication', () => {
    it('authenticates as master when the master key header matches', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-master-key': 'masterKey',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(auth.Auth).toHaveBeenCalledTimes(1);
      expect(auth.Auth.mock.calls[0][0]).toMatchObject({
        config: appConfig,
        isMaster: true,
      });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('authenticates as maintenance when the maintenance key header matches', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-maintenance-key': 'maintenanceKey',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(auth.Auth.mock.calls[0][0]).toMatchObject({ isMaintenance: true });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('skips key resolution when auth was already resolved as master', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-master-key': 'masterKey',
        },
      });
      req.config = appConfig;
      req.auth = { isMaster: true, isMaintenance: false };
      const res = createRes();

      await runHeaders(req, res, next);

      expect(appConfig.loadMasterKey).not.toHaveBeenCalled();
      expect(req.auth).toEqual({ isMaster: true, isMaintenance: false });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('does not authenticate as master when the master key does not match', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-master-key': 'wrong-key',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(auth.Auth.mock.calls[0][0]).toMatchObject({ isMaster: false });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('rejects the request when the master key is used from a non allowed ip', async () => {
      appConfig.masterKeyIps = ['10.0.0.0/8'];
      appConfig.masterKeyIpsStore = new Map();
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-master-key': 'masterKey',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await expect(handleParseHeaders(req, res, next)).rejects.toMatchObject({
        status: 403,
        message: 'unauthorized',
      });
      expect(appConfig.loggerController.error).toHaveBeenCalled();
      expect(next).not.toHaveBeenCalled();
    });
  });

  describe('client key validation', () => {
    it('allows the request when a configured client key matches', async () => {
      appConfig.clientKey = 'configured-client-key';
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-client-key': 'configured-client-key',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(next).toHaveBeenCalledTimes(1);
      expect(res.status).not.toHaveBeenCalled();
    });

    it('rejects the request when a configured client key does not match', async () => {
      appConfig.clientKey = 'configured-client-key';
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-client-key': 'a-wrong-key',
        },
      });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it('rejects the request when a configured client key is not provided', async () => {
      appConfig.clientKey = 'configured-client-key';
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it('does not validate client keys when none are configured', async () => {
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(next).toHaveBeenCalledTimes(1);
    });
  });

  describe('server state', () => {
    it('responds with 500 when the server state is not ok', async () => {
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      req.config.state = 'starting';
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(500);
      expect(res.json).toHaveBeenCalledWith({
        code: Parse.Error.INTERNAL_SERVER_ERROR,
        error: 'Invalid server state: starting',
      });
      expect(next).not.toHaveBeenCalled();
    });

    it('continues when the server state is ok', async () => {
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      req.config.state = 'ok';
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).not.toHaveBeenCalled();
      expect(next).toHaveBeenCalledTimes(1);
    });
  });

  describe('session token and route handling', () => {
    it('drops the session token for the /login route', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-session-token': 'r:some-session',
        },
      });
      req.path = '/login';
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.sessionToken).toBeUndefined();
      expect(auth.Auth.mock.calls[0][0]).toMatchObject({ isMaster: false });
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('keeps the session token for other routes', async () => {
      const req = createReq({
        headers: {
          'x-parse-application-id': 'testAppId',
          'x-parse-session-token': 'r:some-session',
        },
      });
      req.path = '/classes/Test';
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(req.info.sessionToken).toBe('r:some-session');
    });

    it('builds an authenticated request from req.userFromJWT', async () => {
      const userFromJWT = { id: 'user-id-1' };
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      req.userFromJWT = userFromJWT;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(auth.Auth).toHaveBeenCalledTimes(1);
      expect(auth.Auth.mock.calls[0][0]).toMatchObject({
        config: appConfig,
        isMaster: false,
        user: userFromJWT,
      });
      expect(next).toHaveBeenCalledTimes(1);
    });
  });

  describe('rate limits', () => {
    it('runs matching rate limit handlers before calling next', async () => {
      const handler = jest.fn((req, res, cb) => cb());
      appConfig.rateLimits = [{ path: /^\/classes/, handler }];
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(handler).toHaveBeenCalledTimes(1);
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('skips rate limit handlers whose path does not match', async () => {
      const handler = jest.fn((req, res, cb) => cb());
      appConfig.rateLimits = [{ path: /^\/functions/, handler }];
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(handler).not.toHaveBeenCalled();
      expect(next).toHaveBeenCalledTimes(1);
    });

    it('responds with 429 when a rate limit handler fails with a connection error', async () => {
      const error = new Error('too many');
      error.code = Parse.Error.CONNECTION_FAILED;
      const handler = jest.fn((req, res, cb) => cb(error));
      appConfig.rateLimits = [{ path: /^\/classes/, handler }];
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(res.status).toHaveBeenCalledWith(429);
      expect(res.body).toEqual({
        code: Parse.Error.CONNECTION_FAILED,
        error: 'too many',
      });
      expect(next).not.toHaveBeenCalled();
    });

    it('logs other rate limit errors and still calls next', async () => {
      const handler = jest.fn((req, res, cb) => cb(new Error('unexpected')));
      appConfig.rateLimits = [{ path: /^\/classes/, handler }];
      const req = createReq({ headers: { 'x-parse-application-id': 'testAppId' } });
      req.config = appConfig;
      const res = createRes();

      await runHeaders(req, res, next);

      expect(appConfig.loggerController.error).toHaveBeenCalled();
      expect(res.status).not.toHaveBeenCalled();
      expect(next).toHaveBeenCalledTimes(1);
    });
  });
});
